signed-standalone.run:
python tools/release_version.py --check
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$releaseRoot = Join-Path $env:RUNNER_TEMP 'eqnedit64-draft'
python tools/check_release_versions.py --artifact "$releaseRoot/EqnEdit64.exe" --artifact "$releaseRoot/EqnEdit64.release.json" --artifact web/equation-editor.js --artifact web/equation-editor.fragment.html
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }

build-wheels.run:
$directory = Join-Path $env:RUNNER_TEMP 'eqnedit64-release'
$exe = Join-Path $directory 'EqnEdit64.exe'
$checksums = Join-Path $directory 'SHA256SUMS.txt'
$line = Get-Content -LiteralPath $checksums |
  Where-Object { $_ -match 'EqnEdit64\.exe$' } | Select-Object -First 1
if (-not $line) { throw 'EqnEdit64.exe checksum is missing' }
$expected = ($line -split '\s+')[0].ToUpperInvariant()
$actual = (Get-FileHash -Algorithm SHA256 -LiteralPath $exe).Hash
if ($actual -ne $expected) {
  throw "SHA-256 mismatch: $actual != $expected"
}
$signature = Get-AuthenticodeSignature -LiteralPath $exe
$pin = $env:EQNEDIT64_SIGNER_SHA256
if ($pin -notmatch '^[0-9A-Fa-f]{64}$') { throw 'Signer SHA256 setting required' }
$actualPin = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($signature.SignerCertificate.RawData))
if ($actualPin -cne $pin.ToUpperInvariant()) { throw 'Signer certificate mismatch' }
$store = [Security.Cryptography.X509Certificates.X509Store]::new('Root', 'LocalMachine')
try {
  $store.Open('ReadWrite')
  $store.Add($signature.SignerCertificate)
} finally { $store.Close() }
$signature = Get-AuthenticodeSignature -LiteralPath $exe
if ($signature.Status -ne 'Valid') { throw 'Invalid staged signature after pinned trust setup' }

"EQNEDIT64_RELEASE_EXE=$exe" |
  Out-File -FilePath $env:GITHUB_ENV -Append -Encoding utf8

$line = Select-String -LiteralPath python\pyproject.toml `
  -Pattern '^version\s*=\s*"([^"]+)"$' | Select-Object -First 1
if (-not $line) { throw 'eqnedit64 package version is missing' }
$version = $line.Matches[0].Groups[1].Value
if ($env:EQNEDIT64_TAG -cne "v$version") {
  throw "tag/package mismatch: $env:EQNEDIT64_TAG != v$version"
}

$wheel = Get-ChildItem python\dist\eqnedit64-*.whl |
  Select-Object -First 1
$target = Join-Path $env:RUNNER_TEMP 'eqnedit64-wheel-test'
python -m pip install --target $target $wheel.FullName
$env:PYTHONPATH = $target
Push-Location $env:RUNNER_TEMP
try {
  python "$env:GITHUB_WORKSPACE\python\tests\verify_installed.py"
} finally {
  Pop-Location
}

$wheel = Get-ChildItem python/dist/eqnedit64-*.whl | Select-Object -First 1
python tools/check_release_versions.py --artifact $wheel.FullName --artifact $env:EQNEDIT64_RELEASE_EXE
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$version = "${{ needs.qualify.outputs.tag }}".Substring(1)
python tools/check_release_wheels.py --wheel-dir python/dist --standalone $env:EQNEDIT64_RELEASE_EXE --version $version --source-sha "${{ needs.qualify.outputs.sha }}" --python-version "${{ matrix.python-version }}"
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
python tests/check_public_names.py --artifact $wheel.FullName --artifact $env:EQNEDIT64_RELEASE_EXE
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
